function resolvePropertyMutationAuthority(prog, actor, combinedFacts, subject) {
  if (hasSubjectMutationAuthority(combinedFacts, actor, subject)) return {
    allowed: true, mode: "subject", authoritySubject: subject, helperTargets: Object.freeze([]),
  };
  const helperTargets = helperMutationAuthorityTargets(combinedFacts, subject);
  const scopedTargets = scopedAuthorityTargets(combinedFacts, subject);
  const targets = uniqueRefList([...helperTargets, ...scopedTargets]);
  const authoritySubject = targets.find(target => hasSubjectMutationAuthority(combinedFacts, actor, target));
  if (authoritySubject !== undefined) return {
    allowed: true,
    mode: helperTargets.includes(authoritySubject) ? "helper-target" : "scope-target",
    authoritySubject,
    helperTargets: targets,
  };
  return { allowed: false, mode: "", authoritySubject: "", helperTargets: targets };
}

function scopedAuthorityTargets(facts, subject) {
  return walkScopeTargets(asStore(facts), subject, new Set());
}

function duplicateContractValueReason(contract, value, context) {
  if (context.operation !== POLICY.duplicateOperation) return "";
  const slot = Object(contract.slot);
  const explicit = Array.isArray(context.existingValues) ? context.existingValues : [];
  const values = explicit.length ? explicit : existingContractValues(contract);
  if (!values.includes(String(value))) return "";
  const eligible = [Boolean(contract.compatibleRefType), Array.isArray(slot.allowed) && slot.allowed.length > 0].includes(true);
  if (!eligible) return "";
  return slotIsRef(slot) ? POLICY.duplicateReferenceReason : POLICY.duplicateScalarReason;
}

function validateContractValue(contract, value, context, helpers) {
  const intrinsic = validateContractIntrinsicValue(contract, value);
  const duplicate = duplicateContractValueReason(contract, value, context);
  const reason = intrinsic ? intrinsic : duplicate;
  if (!reason) return;
  const slot = Object(contract.slot);
  const subject = text(contract.subject, "<unknown>");
  const predicate = text(slot.predicate, "");
  helpers.failSemantic(helpers.mutationIssue(
    "invalid-mutation-value",
    `Mutation value for ${subject}.${predicate} is invalid: ${reason}.`,
    { subject: text(contract.subject, ""), predicate, value, reason },
  ), { statusCode: 400 });
}

function executeDeleteSubjectMutation(input, helpers) {
  const { dynamicFacts, subject, meta } = input;
  helpers.authorize();
  const incoming = helpers.currentIncomingActiveFacts(dynamicFacts, subject);
  if (incoming.length) {
    helpers.fail(helpers.issue(
      POLICY.incomingDiagnostic,
      `Subject ${subject} cannot be deleted while other facts still reference it.`,
      { subject, references: incoming.map(fact => ({ subject: fact.s, predicate: fact.p })) },
    ), { statusCode: POLICY.incomingStatus });
  }
  const currentFacts = dynamicFacts.factsForSubject(subject).filter(fact => fact.pol === POLICY.currentPolarity);
  if (!currentFacts.length) {
    helpers.fail(helpers.issue(
      POLICY.emptyDiagnostic,
      `Subject ${subject} has no current facts to delete.`,
      { subject },
    ), { statusCode: POLICY.emptyStatus });
  }
  return currentFacts.map(fact => helpers.deltaFact(subject, fact.p, fact.o, POLICY.deltaPolarity, meta));
}

function activeInterface(record, interfaces, helpers) {
  const types = Array.isArray(record?.[POLICY.typeField]) ? record[POLICY.typeField] : [];
  const matches = types.filter(type => interfaces.has(type));
  if (matches.length > 1) {
    const subject = record?.[POLICY.subjectField] ? record[POLICY.subjectField] : POLICY.missingSubjectIdentity;
    helpers.fail(helpers.issue(
      POLICY.ambiguousInterfaceDiagnostic,
      `Subject matches multiple schema interfaces: ${matches.join(", ")}.`,
      { subject },
    ));
  }
  return matches.length ? interfaces.get(matches[0]) : null;
}

function canonicalizeMutationValue(slot, mutation, subject, helpers) {
  const mimeType = mutation.mimeType === undefined ? POLICY.missingMimeType : mutation.mimeType;
  try {
    return canonicalizeSlotValue(slot, mutation.value, { mimeType });
  } catch (error) {
    const valueType = slot.valueType ? slot.valueType : POLICY.missingValueType;
    helpers.fail(helpers.issue(
      POLICY.invalidValueDiagnostic,
      `Mutation value for ${subject}.${slot.predicate} is not a canonical ${valueType}: ${error.message}`,
      { subject, predicate: slot.predicate, valueType, value: mutation?.value },
    ), { statusCode: POLICY.invalidValueStatus });
  }
}
